INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(7612820, 1231825, 113411, '<td valign="top">Brilliant! Congratulations Rob!</td>', 'Brilliant! Congratulations Rob!', '2019-02-08 11:38:56.000000', NULL, 0),
(7612821, 1231871, 24454, '<td valign="top">This is amazing!  I want to give it a 10 right now!</td>', 'This is amazing!  I want to give it a 10 right now!', '2019-02-08 11:39:11.000000', NULL, 0),
(7612822, 1231914, 113411, '<td valign="top">This is too fabulous! I love everything about it.</td>', 'This is too fabulous! I love everything about it.', '2019-02-08 11:41:57.000000', NULL, 0),
(7612823, 1231935, 24454, '<td valign="top">Oh no... not boring at all!  I love it as an art piece.   I love the negative space.  The pose.  The reflection.  And the texture.  I love photographing these birds so much.  But I wonder if the voting community sees them too often and insists on somehing spectacular now, like in flight with a fish in its mouth at sunset with every gnat on its head in perfect focus.  But any rate... this is beautiful!<br/> <br/></td>', 'Oh no... not boring at all!  I love it as an art piece.   I love the negative space.  The pose.  The reflection.  And the texture.  I love photographing these birds so much.  But I wonder if the voting community sees them too often and insists on somehing spectacular now, like in flight with a fish in its mouth at sunset with every gnat on its head in perfect focus.  But any rate... this is beautiful! ', '2019-02-08 11:46:50.000000', NULL, 0),
(7612826, 1231889, 135744, '<td valign="top">Beautiful photography. I am curious where this wonderful place is?</td>', 'Beautiful photography. I am curious where this wonderful place is?', '2019-02-08 12:20:28.000000', NULL, 0),
(7612827, 1231825, 135744, '<td valign="top">It is the first time I have seen a photo like this and I am very impressed. Congrats on the blue.</td>', 'It is the first time I have seen a photo like this and I am very impressed. Congrats on the blue.', '2019-02-08 12:21:27.000000', NULL, 0),
(7612828, 1231594, 135744, '<td valign="top">What an amazing experience that must have been and you have captured it so well. Congrats on the HM!</td>', 'What an amazing experience that must have been and you have captured it so well. Congrats on the HM!', '2019-02-08 12:22:29.000000', NULL, 0),
(7612829, 1231889, 109387, '<td valign="top"><table align="center" width="95%"><tr><td><div class="textsm"><b>Originally posted by P-A-U-L:</b></div><hr/><i> Beautiful photography. I am curious where this wonderful place is? </i></td></tr></table> <br/> <br/>It''s in my region, Abruzzo, central Italy. Check the 7th image by <img alt="'' . substr(''https://www.dpchallenge.com/images/user_icon/21.gif'', strrpos(''https://www.dpchallenge.com/images/user_icon/21.gif'', ''/'') + 1) . ''" border="0" src="https://www.dpchallenge.com/images/user_icon/21.gif"/> <a href="https://www.dpchallenge.com/profile.php?USER_ID=172697" rel="nofollow" target="_blank">waitingsilence</a>: that castle is what you have behind you when you take a photo of this church here. No need to say that this is a super place. We have the highest mountains in southern Europe.</td>', 'Originally posted by P-A-U-L: Beautiful photography. I am curious where this wonderful place is?   It''s in my region, Abruzzo, central Italy. Check the 7th image by  waitingsilence: that castle is what you have behind you when you take a photo of this church here. No need to say that this is a super place. We have the highest mountains in southern Europe.', '2019-02-08 12:23:43.000000', NULL, 0),
(7612860, 1231825, 179769, '<td valign="top">This is absolutely amazing.  I spent a LOT of time trying to figure out where the camels were!   Finally located them on zoom.  I''ve never tried droning, but this makes me want to get off my keister and give it a shot (pun intended).  :-)  GORGEOUS photo.   Thank you and congrats on the blue!</td>', 'This is absolutely amazing.  I spent a LOT of time trying to figure out where the camels were!   Finally located them on zoom.  I''ve never tried droning, but this makes me want to get off my keister and give it a shot (pun intended).  :-)  GORGEOUS photo.   Thank you and congrats on the blue!', '2019-02-08 16:36:18.000000', NULL, 0),
(7612890, 1231594, 1031, '<td valign="top">Great photo, though not the weather I''d have expected to see there. :-)<br/> <br/>Did you have a chance (or inclination) to visit <a href="https://en.wikipedia.org/wiki/Ernest_Shackleton" rel="nofollow" target="_blank">Shackleton''s</a> gravesite?</td>', 'Great photo, though not the weather I''d have expected to see there. :-) Did you have a chance (or inclination) to visit Shackleton''s gravesite?', '2019-02-08 18:26:01.000000', NULL, 0),
(7612902, 1231594, 115664, '<td valign="top">Yes we did visit Shackleton''s grave. Toasted the man himself. We also visited Elephant Island where he was shipwrecked in Antarctica and had to leave men to go for help in a lifeboat. A British member of our expedition team re-enacted that voyage in a replica of the lifeboat with only what Shackleton would have had with him! Clothing, food etc! An epic voyage accross the southern ocean from Antarctica to South Georgia.</td>', 'Yes we did visit Shackleton''s grave. Toasted the man himself. We also visited Elephant Island where he was shipwrecked in Antarctica and had to leave men to go for help in a lifeboat. A British member of our expedition team re-enacted that voyage in a replica of the lifeboat with only what Shackleton would have had with him! Clothing, food etc! An epic voyage accross the southern ocean from Antarctica to South Georgia.', '2019-02-08 21:35:09.000000', NULL, 0),
(7613057, 1231679, 100831, '<td valign="top">This is awesome.</td>', 'This is awesome.', '2019-02-10 16:07:09.000000', NULL, 0),
(7613071, 1231475, 114285, '<td valign="top">Youre not wrong about that, is he your grandson?? no that cant be, what a handsome young boy.</td>', 'Youre not wrong about that, is he your grandson?? no that cant be, what a handsome young boy.', '2019-02-10 18:40:49.000000', NULL, 0),
(7613213, 1231952, 124815, '<td valign="top">Oh, I did hope that you took the shot with your Fuji!</td>', 'Oh, I did hope that you took the shot with your Fuji!', '2019-02-11 10:08:48.000000', NULL, 0),
(7613611, 1231889, 86447, '<td valign="top">Back to look again... it''s so good!<br/> <br/>I have to wonder now, though...   What''s your "Message for God"?<br/> <br/>I''m interested.<br/> <br/></td>', 'Back to look again... it''s so good! I have to wonder now, though...   What''s your "Message for God"? I''m interested. ', '2019-02-14 22:02:55.000000', NULL, 0);
